<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3';
import { computed, onBeforeUnmount, ref } from 'vue';
import { ImageIcon, Pencil } from '@lucide/vue';
import PageHeader from '@/Components/Shared/PageHeader.vue';
import ImageEditorDialog, { type ImageEditData, type ImageEditorPreset } from '@/components/media/ImageEditorDialog.vue';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';

const props = defineProps<{ campaign: any; creative?: any | null }>();
const selectedOriginal = ref<File | null>(null);
const originalSource = ref<File | string | null>(props.creative?.original_media_url ?? props.creative?.media_url ?? null);
const editedPreview = ref<string | null>(props.creative?.media_url ?? null);
const editorOpen = ref(false);
const editData = ref<ImageEditData | null>(props.creative?.media_edit_data ?? null);
const selectedPlacement = computed(() => props.campaign.placements.find((x: any) => Number(x.id) === Number(form.placement_ids[0])) ?? null);
function isCompatiblePlacement(placement: any): boolean {
    const primary = selectedPlacement.value;
    if (!primary || !primary.width || !primary.height || !placement.width || !placement.height) return true;
    return Number(primary.width) === Number(placement.width) && Number(primary.height) === Number(placement.height);
}
const preset = computed<ImageEditorPreset>(() => ({ key: `ad-${selectedPlacement.value?.id ?? 'custom'}`, label: selectedPlacement.value?.name ?? 'Advertising creative', width: selectedPlacement.value?.width ?? 1200, height: selectedPlacement.value?.height ?? 628, outputType: 'image/jpeg', quality: .9 }));
const form = useForm({ placement_ids: (props.creative?.placements?.map((x: any) => x.id) ?? [props.creative?.ad_placement_id ?? props.campaign.placements?.[0]?.id]).filter(Boolean), name: props.creative?.name ?? '', creative_type: props.creative?.creative_type ?? 'image', media_original: null as File | null, media: null as File | null, media_edit_data: props.creative?.media_edit_data ? JSON.stringify(props.creative.media_edit_data) : '', width: props.creative?.width ?? null, height: props.creative?.height ?? null, headline: props.creative?.headline ?? '', body: props.creative?.body ?? '', cta_label: props.creative?.cta_label ?? '', destination_url: props.creative?.destination_url ?? '', alt_text: props.creative?.alt_text ?? '' });
function chooseMedia(e: Event) { const file=(e.target as HTMLInputElement).files?.[0]??null;if(!file)return;if(file.type.startsWith('image/')){selectedOriginal.value=file;originalSource.value=file;form.media_original=file;form.creative_type='image';editorOpen.value=true;}else{form.media=file;form.creative_type='video';} }
function applyEdited(payload:{file:File;edit:ImageEditData;previewUrl:string}){if(editedPreview.value?.startsWith('blob:'))URL.revokeObjectURL(editedPreview.value);editedPreview.value=payload.previewUrl;editData.value=payload.edit;form.media=new File([payload.file],payload.file.name||'advertising-creative.jpg',{type:payload.file.type||'image/jpeg',lastModified:Date.now()});form.media_edit_data=JSON.stringify(payload.edit);form.width=payload.edit.outputWidth;form.height=payload.edit.outputHeight;}
function save(){const url=props.creative?`/admin/ad-campaigns/${props.campaign.id}/creatives/${props.creative.id}`:`/admin/ad-campaigns/${props.campaign.id}/creatives`;form.transform(d=>props.creative?{...d,_method:'put'}:d).post(url,{forceFormData:true});}
onBeforeUnmount(()=>{if(editedPreview.value?.startsWith('blob:'))URL.revokeObjectURL(editedPreview.value)});
</script>
<template><Head :title="creative?'Edit Creative':'Add Creative'"/><form class="space-y-6 p-6" @submit.prevent="save"><PageHeader :title="creative?'Edit Advertising Creative':'Add Advertising Creative'" :description="`${campaign.name} · Images use the placement-aware editor before upload.`"/><ImageEditorDialog v-model:open="editorOpen" :source="originalSource" :filename="selectedOriginal?.name ?? 'advertising-creative.jpg'" :preset="preset" :initial-edit="editData" @apply="applyEdited"/><div class="grid gap-6 xl:grid-cols-2"><section class="rounded-xl border p-5"><h2 class="font-semibold">Creative media</h2><div class="mt-4 space-y-4"><label class="block text-sm">Name<Input v-model="form.name" class="mt-2"/></label><fieldset class="space-y-2"><legend class="text-sm font-medium">Placements <span class="text-destructive">*</span></legend><p class="text-xs text-muted-foreground">Select every campaign placement where this creative should run. Placements with different dimensions are disabled.</p><label v-for="x in campaign.placements" :key="x.id" class="flex items-center gap-3 rounded-md border p-3 text-sm" :class="{ 'opacity-50': !isCompatiblePlacement(x) && !form.placement_ids.includes(x.id) }"><input v-model="form.placement_ids" type="checkbox" :value="x.id" :disabled="!isCompatiblePlacement(x) && !form.placement_ids.includes(x.id)"/><span>{{x.name}} — {{x.width || 'flex'}} × {{x.height || 'flex'}}</span></label><p v-if="form.errors.placement_ids" class="text-sm text-destructive">{{ form.errors.placement_ids }}</p></fieldset><label class="block text-sm">Creative type<select v-model="form.creative_type" class="mt-2 h-10 w-full rounded-md border bg-background px-3"><option value="image">Image</option><option value="video">Video</option></select></label><label class="block text-sm">{{creative?'Replace media':'Creative file'}}<input type="file" class="mt-2 block w-full text-sm" :accept="form.creative_type==='image'?'image/jpeg,image/png,image/webp':'video/mp4,video/webm'" @change="chooseMedia"/></label><div v-if="form.creative_type==='image' && editedPreview" class="overflow-hidden rounded-xl border bg-muted"><img :src="editedPreview" alt="Edited advertising creative preview" class="w-full object-contain"/><div class="flex items-center justify-between p-3"><span class="flex items-center gap-2 text-sm"><ImageIcon class="h-4 w-4"/>{{preset.width}} × {{preset.height}}</span><Button type="button" size="sm" variant="outline" @click="editorOpen=true"><Pencil class="mr-2 h-4 w-4"/>Edit crop</Button></div></div><p class="text-xs text-muted-foreground">The original source is retained. The edited placement-ready image is used for delivery.</p><p v-for="e in Object.values(form.errors)" class="text-sm text-destructive">{{e}}</p></div></section><section class="rounded-xl border p-5"><h2 class="font-semibold">Message and destination</h2><div class="mt-4 space-y-4"><label class="block text-sm">Headline<Input v-model="form.headline" class="mt-2"/></label><label class="block text-sm">Body<textarea v-model="form.body" rows="4" class="mt-2 w-full rounded-md border bg-background p-3"/></label><label class="block text-sm">CTA label<Input v-model="form.cta_label" class="mt-2"/></label><label class="block text-sm">Destination URL <span class="text-destructive">*</span><Input v-model="form.destination_url" type="url" required placeholder="https://example.com/landing-page" class="mt-2"/><p class="mt-1 text-xs text-muted-foreground">Required. Visitors are sent here when they click the advertisement.</p><p v-if="form.errors.destination_url" class="mt-1 text-sm text-destructive">{{ form.errors.destination_url }}</p></label><label class="block text-sm">Alternative text<textarea v-model="form.alt_text" rows="3" class="mt-2 w-full rounded-md border bg-background p-3"/></label></div></section></div><div class="flex justify-end gap-3"><Button type="button" variant="outline" @click="history.back()">Cancel</Button><Button :disabled="form.processing">{{form.processing?'Saving...':'Save Creative'}}</Button></div></form></template>
